// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

require('dotenv').config();

const express = require('express');
const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Conditional middleware based on environment
if (NODE_ENV === 'production') {
  // In production, you might want to add more security middleware
  // const helmet = require('helmet');
  // app.use(helmet());
}

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get('/users', (req, res) => {
  // In a real application, this would come from a database
  // For demo/test purposes, we're keeping it here but could be made configurable
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${NODE_ENV} mode on http://${HOST}:${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

