// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

// Configuration from environment variables with sensible defaults
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: process.env.SERVICE_NAME || 'user-service'
  });
});

app.get('/users', (req, res) => {
  // In a real app, this would come from a database
  // For demo purposes, we'll use configurable mock data
  const mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Allow override via environment for testing different scenarios
  if (process.env.MOCK_USER_COUNT) {
    const count = parseInt(process.env.MOCK_USER_COUNT);
    return res.json(
      Array.from({ length: count }, (_, i) => ({
        id: i + 1,
        name: `User${i + 1}`,
        email: `user${i + 1}@example.com`
      }))
    );
  }

  res.json(mockUsers);
});

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
});

// For testing purposes
module.exports = { app, server };

